import { AfterViewInit, Component, HostBinding, Input, OnDestroy, ViewChild } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatMenuModule, MatMenuTrigger } from '@angular/material/menu';
import { MatTooltipModule } from '@angular/material/tooltip';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatRadioModule } from '@angular/material/radio';
import { TranslateModule } from '@ngx-translate/core';
import { Subscription } from 'rxjs';
import { IconComponent } from '../icon/icon.component';
import { SelectionActionsService } from '../../services/selection-actions/selection-actions.service';

@Component({
  selector: 'selection-actions-control',
  standalone: true,
  imports: [CommonModule, MatMenuModule, MatTooltipModule, MatCheckboxModule, MatRadioModule, TranslateModule, IconComponent],
  templateUrl: './selection-actions-control.component.html',
  styleUrl: './selection-actions-control.component.scss',
})
export class SelectionActionsControlComponent implements AfterViewInit, OnDestroy {
  @Input() dark: boolean = false;
  @Input() compact: boolean = false;
  @Input() showLabel: boolean = true;
  /** When true, render as a small dark icon-only switcher used inside the
   *  selection popup (annot-box / toolbox). Suppresses the label, detail
   *  text, chevron, and pill chrome — leaves just the cursor icon. Click
   *  asks the service to open the toolbar's dropdown rather than rendering
   *  a local one, so the menu anchors to the toolbar pill. */
  @Input() iconOnly: boolean = false;

  /** Bound to host so :host.icon-only can switch from inline-flex to a
   *  full-width block — the switcher lives inside the dark popup and must
   *  stretch across, not collapse to its content width. */
  @HostBinding('class.icon-only') get hostIconOnly(): boolean { return this.iconOnly; }

  @ViewChild(MatMenuTrigger) menuTrigger?: MatMenuTrigger;
  private openSub?: Subscription;

  constructor(public readonly sa: SelectionActionsService) {}

  ngAfterViewInit(): void {
    // Only the toolbar pill (non-iconOnly) hosts the dropdown. Subscribe to
    // open requests fired by remote switchers (icon-only buttons inside
    // selection popups) so they appear anchored here.
    if (!this.iconOnly) {
      this.openSub = this.sa.openToolbar$.subscribe(() => this.menuTrigger?.openMenu());
    }
  }

  ngOnDestroy(): void {
    this.openSub?.unsubscribe();
  }

  onSwitcherClick(): void {
    this.sa.requestOpenToolbar();
  }

  get label(): string {
    if (this.sa.isCopy()) return 'Copy Mode';
    if (this.sa.isSingle()) return this.sa.modeLabel()!;
    return 'Actions';
  }

  get detail(): string | null {
    if (this.sa.isCopy() || this.sa.isSingle()) return null;
    return this.sa.activeArr().map(k => k === 'QF' ? 'QFact' : k === 'F' ? 'Fact' : 'DocLink').join(' • ');
  }

  /** Bold prefix in the dropdown footer (e.g. "QFact"). Defaults to "Actions"
   *  in the multi-mode (Fact + DocLink) state so the footer reads
   *  "Actions: Select text, then choose between Fact and DocLink." */
  get footerLabel(): string | null {
    if (this.sa.isCopy()) return 'Copy';
    if (this.sa.isQFactRapid()) return 'QFact';
    if (this.sa.singleKind() === 'F') return 'Fact';
    if (this.sa.singleKind() === 'D') return 'DocLink';
    return 'Actions';
  }

  /** Contextual help text under the action list. Copy comes from the spec
   *  in chat (2026-04-28); the only reachable multi state is Fact + DocLink
   *  because QFact is exclusive in the radio group. */
  get footerHint(): string {
    if (this.sa.isCopy()) return 'Text is copied as soon as it is selected.';
    if (this.sa.isQFactRapid()) return 'Pre-select issues or use Unassigned, then capture by selecting text.';
    if (this.sa.singleKind() === 'F') return 'Select text, then add issues and supporting details.';
    if (this.sa.singleKind() === 'D') return 'Select text, then choose the linked document.';
    return 'Select text, then choose between Fact and DocLink.';
  }

  /** Current exclusive radio mode — drives the mat-radio-group [value].
   *  Returns 'QF' when QFact is armed, 'COPY' when Copy is armed,
   *  or '' when the user is in additive Fact/DocLink checkbox mode
   *  (no radio selected). */
  get radioMode(): string {
    if (this.sa.state().qf) return 'QF';
    if (this.sa.isCopy()) return 'COPY';
    return '';
  }

  onRadioChange(event: any): void {
    if (event.value === 'QF') this.setQFact();
    else if (event.value === 'COPY') this.setCopy();
  }

  setQFact(): void { this.sa.setQFact(); }
  setCopy(): void { this.sa.setCopy(); }
  toggleAdditive(key: 'fact' | 'doclink'): void { this.sa.toggleAdditive(key); }

  setQfNote(checked: boolean): void { this.sa.setQfSubOption('qfIncludeNote', checked); }
  setQfTextNote(checked: boolean): void { this.sa.setQfSubOption('qfIncludeTextPlusNote', checked); }
  setCopyDocName(checked: boolean): void { this.sa.setCopySubOption('copyDocName', checked); }
  setCopyPagination(checked: boolean): void { this.sa.setCopySubOption('copyPagination', checked); }
}
